/** `mcp serve`, `mcp install`, `mcp oauth`: expose an agent to MCP clients. */
import { defineCommand } from "../command.js";
import { apiKeyFlag, bearerTokenFlag, dirFlag, dryRunFlag, jsonFlag, printAliasFlag, prodRejectedFlag, slugFlag, teamFlag, urlFlag, } from "../flags.js";
export const mcpServeCommand = defineCommand({
    name: "mcp serve",
    // MCP client configs written before `mcp serve` run bare `bdk mcp`. It
    // stays quiet: stdout is the MCP wire and clients log stderr.
    aliases: [{ name: "mcp", silent: true }],
    group: "develop",
    parentSummary: "Expose a running agent to MCP clients.",
    summary: "Serve a running agent's MCP endpoint over stdio for MCP clients.",
    description: "Proxies newline-delimited JSON-RPC to <url>/v1/mcp for clients that spawn local servers, such as Cursor. stdout is the MCP wire.",
    flags: { ...urlFlag, ...bearerTokenFlag, ...prodRejectedFlag },
    effect: "interactive",
    examples: ["agent-sdk mcp serve --url http://127.0.0.1:3000/my-agent"],
    async run({ values }) {
        const { cmdMcp } = await import("../../cli-mcp.js");
        return cmdMcp(undefined, {
            dir: ".",
            url: values.url,
            prod: values.prod,
            bearerToken: values["bearer-token"],
        });
    },
});
export const mcpInstallCommand = defineCommand({
    name: "mcp install",
    group: "develop",
    summary: "Write an MCP client entry for a running agent into ~/.cursor/mcp.json.",
    flags: {
        ...urlFlag,
        ...bearerTokenFlag,
        name: { type: "string", value: "<serverName>", description: "Override the MCP server name." },
        "dry-run": { type: "boolean", description: "Print the entry. Write nothing." },
        ...printAliasFlag,
        ...jsonFlag,
        ...prodRejectedFlag,
        remote: {
            type: "boolean",
            hidden: true,
            description: "Not supported. Prints the hosted alternative and exits 2.",
        },
    },
    effect: "write",
    async run({ values }) {
        const { cmdMcp } = await import("../../cli-mcp.js");
        return cmdMcp("install", {
            dir: ".",
            url: values.url,
            prod: values.prod,
            remote: values.remote,
            bearerToken: values["bearer-token"],
            name: values.name,
            print: values["dry-run"] === true || values.print === true,
            json: values.json,
        });
    },
});
export const mcpOauthCommand = defineCommand({
    name: "mcp oauth",
    group: "develop",
    summary: "Authorize defineConnection({ url, oauth: true }) with host PKCE.",
    description: "--store writes the tokens as MCP_OAUTH_<NAME>_* secrets on the hosted deployment.",
    args: [{ name: "connection", description: "Connection name.", required: true }],
    flags: {
        ...dirFlag,
        store: {
            type: "boolean",
            description: "Store the tokens as secrets on the hosted deployment.",
        },
        ...dryRunFlag,
        ...slugFlag,
        ...teamFlag,
        ...apiKeyFlag,
    },
    effect: "write",
    async run({ values, positionals }) {
        const { cmdMcp } = await import("../../cli-mcp.js");
        return cmdMcp("oauth", {
            dir: values.dir,
            oauthConnection: positionals[0],
            store: values.store,
            dryRun: values["dry-run"],
            slug: values.slug,
            team: values.team,
            apiKey: values["api-key"],
        });
    },
});
